import{c as e,Q as a,j as r,m as s}from"./chunks/framework.dywCjXaF.js";const g=JSON.parse('{"title":"Run History","description":"","frontmatter":{},"headers":[],"relativePath":"run-history.md","filePath":"run-history.md"}'),o={name:"run-history.md"};function i(n,t,h,l,d,u){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="run-history" tabindex="-1">Run History <a class="header-anchor" href="#run-history" aria-label="Permalink to &quot;Run History&quot;">​</a></h1><p>The <strong>Run History</strong> tab lists every historical run that Sarva-Varadi has recorded. It is the sixth sidebar tab and the heart of the cross-run analysis feature.</p><nav class="table-of-contents"><ul><li><a href="#what-it-shows">What it shows</a></li><li><a href="#filters">Filters</a></li><li><a href="#viewing-a-historical-run">Viewing a historical run</a><ul><li><a href="#back-to-latest">Back to Latest</a></li></ul></li><li><a href="#chart-auto-centering">Chart auto-centering</a></li><li><a href="#coverage-changes-while-viewing-history">Coverage Changes while viewing history</a></li><li><a href="#history-storage">History storage</a></li></ul></nav><hr><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><p>Each row in the table represents one past run and shows:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td>Run #</td><td>Sequential run number (most recent = highest)</td></tr><tr><td>Date / Time</td><td>When the run executed</td></tr><tr><td>Status</td><td>Passed / Failed / Flaky based on outcome distribution</td></tr><tr><td>Pass Rate</td><td>% of tests that passed</td></tr><tr><td>Total</td><td>Total test count</td></tr><tr><td>Duration</td><td>How long the run took</td></tr><tr><td>View →</td><td>Button to load that run into the report</td></tr></tbody></table><hr><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>The filter bar at the top of the tab lets you narrow down runs before browsing. Each filter can be cleared individually (✕) or all at once (Clear All).</p><table tabindex="0"><thead><tr><th>Filter</th><th>Options</th></tr></thead><tbody><tr><td>Date range</td><td>Calendar date pickers — defaults to last 30 days on load</td></tr><tr><td>Status</td><td>All / Passed / Failed / Flaky</td></tr><tr><td>Pass rate</td><td>Min % threshold (e.g. &quot;show only runs ≥ 80%&quot;)</td></tr><tr><td>Duration</td><td>Max seconds (e.g. &quot;show only runs under 300s&quot;)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Default date range</p><p>On first load the date filter defaults to <strong>last 30 days</strong> to avoid rendering hundreds of rows. Clear the date filter (✕) or widen the range to see older runs.</p></div><p><strong>Clear All</strong> resets every filter but restores the 30-day date default rather than showing all runs.</p><hr><h2 id="viewing-a-historical-run" tabindex="-1">Viewing a historical run <a class="header-anchor" href="#viewing-a-historical-run" aria-label="Permalink to &quot;Viewing a historical run&quot;">​</a></h2><p>Click <strong>View →</strong> on any row. The report instantly hot-swaps to that run:</p><ul><li><strong>Overview</strong> re-renders with that run&#39;s stat cards, health pulse, and top lists</li><li><strong>Failures</strong> shows that run&#39;s failures</li><li><strong>Tests</strong> shows that run&#39;s test results</li><li><strong>Trends</strong> and <strong>Timeline</strong> remain on the latest data but place a dashed vertical marker at the selected run&#39;s position</li><li>A <strong>viewing banner</strong> appears at the top of every tab: <code>Viewing Run #N · date · pass rate · duration</code></li></ul><h3 id="back-to-latest" tabindex="-1">Back to Latest <a class="header-anchor" href="#back-to-latest" aria-label="Permalink to &quot;Back to Latest&quot;">​</a></h3><p>The viewing banner includes a <strong>← Back to Latest</strong> link. Click it (or click any nav tab) to restore the current run.</p><hr><h2 id="chart-auto-centering" tabindex="-1">Chart auto-centering <a class="header-anchor" href="#chart-auto-centering" aria-label="Permalink to &quot;Chart auto-centering&quot;">​</a></h2><p>Charts with a run-count filter (Overview Health Pulse, Trends, Timeline Run Cadence) have a <strong>Last 10 / 20 / 50 / All</strong> filter. When you click <strong>View →</strong> on a run that falls outside the current window, the chart automatically centers a 20-run window on the selected run.</p><p>The chart header label changes to reflect this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Runs #51–70 · centered on Run #61</span></span></code></pre></div><p>Clicking any filter button (Last 10, Last 20, etc.) exits centered mode and returns to the normal window.</p><hr><h2 id="coverage-changes-while-viewing-history" tabindex="-1">Coverage Changes while viewing history <a class="header-anchor" href="#coverage-changes-while-viewing-history" aria-label="Permalink to &quot;Coverage Changes while viewing history&quot;">​</a></h2><p>The <strong>New Tests</strong> and <strong>Absent Tests</strong> widgets on Overview are always relative to the <strong>current/latest</strong> run — not the historical run being viewed. They are hidden automatically when a historical run is active, because test-history is not replayed to a point-in-time. A tooltip on each widget notes this behaviour.</p><hr><h2 id="history-storage" tabindex="-1">History storage <a class="header-anchor" href="#history-storage" aria-label="Permalink to &quot;History storage&quot;">​</a></h2><p>History is stored as individual JSON files in <code>sarva-report/history/</code> — one folder per run. The <code>runs.json</code> index is rebuilt by the CLI from those folders each time a report is generated. There is no database; the folder can be committed to git, zipped, or copied as-is.</p><p>In CI, use the pattern of fetching the existing <code>history/</code> folder from your previous deployment before running tests, so history accumulates across CI runs.</p><p>→ See <a href="./architecture.html">Architecture</a> for the full history model.</p>',33)])])}const p=e(o,[["render",i]]);export{g as __pageData,p as default};
